INSERT INTO warscape_enemy_family VALUES (7,'spiders','Spiders','Duskwood venom-web widow display 955, scaled by variant.');
INSERT INTO warscape_enemy_family VALUES (8,'scorpions','Scorpions','Durotar scorpid display 2485, scaled by tier. Poisonous variant deferred.');
